{
  "update_text": "When parsing user JSON, treat it as potentially malformed and defensively normalize it: strip trailing commas, stray quotes artifacts, and any dangling commas before attempting to decode, or report validation failure rather than propagating a decode exception.",
  "rationale": "The token-buffer error stems from a trailing-comma artifact, so proactively stripping trailing (unexpected) commas before coercing JSON prevents the decode exception.",
  "confidence": "medium"
}

{
  "update_text": "When echoing or returning JSON, output only the raw compact JSON object—never append extra tokens (bidirectional feedback like 'Extra value after close', prose quotes, or similar diagnostics) after the closing brace.",
  "rationale": "The error arises because literal prose/diagnostics leaked right after the JSON's closing brace, so this forces the model to end its output with a clean brace and nothing afterward.",
  "confidence": "high"
}

{
  "update_text": "Only include input verbatim as data when user intent is ambiguous; never inject analytics pseudo-fields like 'autogenGenPromptVersion'.\nAlways return exactly as much parsed JSON as the user provided, with no added or 'system-supplied' keys, and strip any malformed JSON trapped in text warnings rather than echoing them.\nExtract the actual user request from any surrounding prose so you don't process fragments like a code snippet plugged into a format string.\",
  "rationale": "\" -- Identifies how the malformed input is injected.\n\" -- Prevents adding Canada,undefined.\n\" -- Identifies the input.\",
  "confidence": "low"
}

{
  "update_text": "Never use or emit invalid JSON values such as raw hex literals (e.g., 0x...); always provide numbers as plain decimal digits and escape any non-ASCII characters in strings to guarantee strictly valid JSON. When unsure whether a value is valid JSON, output a sanitized fallback object with that value ignored.",
  "rationale": "It stops the agent from inserting non-JSON tokens like 0x14 that break JSON parsing, and gives a safe fallback for malformed input.",
  "confidence": "high"
}

{
  "update_text": "Never trust raw user input: before parsing, decode escape sequences as text and verify it is valid JSON, and if parsing fails, output a sanitized fallback object with the problematic value omitted rather than attempting to interpret malformed literals like \\x15.",
  "rationale": "This directly addresses the exception by ensuring the agent validates and sanitizes input before processing instead of assuming untrusted input is well-formed.",
  "confidence": "medium"
}

{
  "update_text": "When parsing user input, detect and report structural JSON errors — specifically, missing colon key/value delimiters — by scanning for absent ':' separators before processing.",
  "rationale": "This directs the agent to recognize the exact failure mode (missing colon) rather than emitting malformed output like {\"Missing colon\" null}.",
  "confidence": "high"
}

{
  "update_text": "Never include a doubled colon (::) when emitting a JSON key; use exactly one ':' separator to separate each key from its value.",
  "rationale": "The error stems from malformed JSON caused by a duplicated ':' in the key ",
  "confidence": "high"
}

{
  "update_text": "When sanitizing or rewriting user input into JSON, represent separators (colons, commas) literally and transparently using forward-slashed escapes (e.g. ': -> \":\"; ', -> \"[, \"] ) so that structural marks are never duplicated or emitted as standalone field values, ensuring the result parses to valid JSON.",
  "rationale": "This directly prevents the doubled comma artifact that produced invalid JSON with an unexpected delimiter position.",
  "confidence": "medium"
}

{
  "update_text": "Always start your response with a '[' to ensure the output is parsed as a JSON array from the first character, never as a bare string token like 'single quote'.",
  "rationale": "The error occurred because the model emitted a quoted-only string instead of actual JSON; forcing an array opener guarantees valid JSON is produced.",
  "confidence": "high"
}

{
  "update_text": "When user input contains literal line breaks or unescaped control characters, serialize the entire input as a single JSON string escaped via a strict JSON encoder so no raw control characters leak into emitted output.",
  "rationale": "The error stems from unescaped control characters in the output, so forcibly escaping them prevents InvalidControlCharacter DecodeErrors, and this addresses JSON string escaping rather than covering the Apache/Thrift control-character whitelist budget, which is irrelevant here.",
  "confidence": "medium"
}

{
  "update_text": "When parsing user input, do not discard leading content such as corruption or spurious characters (e.g., a stray '0' at line 1/column 3) that shifts the parser's column count; additionally, trim leading whitespace before attempting to parse.",
  "rationale": "This targets the specific 'column 3 (char 2)' offset in the error, indicating the parser stalled near the start rather than on genuinely valid JSON data.",
  "confidence": "medium"
}

{
  "update_text": "When user input begins with non-JSON tokens, empty arrays, or whitespace-only content, always respond with a sanitized fallback object (e.g., {\"error\": \"invalid_json\"}) instead of echoing or partially formatting that content.",
  "rationale": "The error shows the agent echoed raw leading brackets from a malformed input like '[   , ...' instead of treating it as invalid JSON, so this enforces fallback-on-malformed-input to prevent echoing raw content.",
  "confidence": "high"
}

{
  "update_text": "When input contains unescaped newlines or structural issues (e.g., raw line breaks that split or extend JSON), read the entire raw input verbatim—do not reformat, trim embedded newlines, or assume whitespace line breaks separate logical JSON documents.",
  "rationale": "The Extra data error arises because the agent processed only the first JSON document and ignored the trailing bytes, indicating the bug is likely in how raw input with unescaped newlines is being segmented rather than in output formatting.",
  "confidence": "medium"
}

{
  "update_text": "When parsing user input as JSON, if a JSONDecodeError occurs, re-transmit the raw input (trimmed and control-character-escaped) separated from the model output with a clear demarcator line so the reader can visually detect trailing tokens like stray 'Extra close' fragments instead of mistaking them for the response.",
  "rationale": "This exposes the misleading multi-line model output where the agent conflated error text with its own reply, helping prevent future autocomplete-style hallucination of 'Extra close'.",
  "confidence": "medium"
}

{
  "update_text": "When generating JSON objects or arrays, format separators so no trailing comma, comma, or comma artifact appears as a standalone value—a comma is purely structural between elements, never a value, and is never emitted inside any string. For any object, ensure each key-value pair is followed by a comma except after the last pair, and prefer compact separators (no trailing separators).",
  "rationale": "The model mistakenly echoed a comma as a value ('Extra comma'); this addition explicitly forbids emitting comma artifacts and specifies correct trailing-comma handling for object/array elements.",
  "confidence": "high"
}

{
  "update_text": "When an emitted value contains multiple tokens or operators (e.g., '1 + 2'), wrap the entire expression as a single quoted JSON string with escaped internal spaces, never emit arithmetic operators or unquoted bare numbers/spaces as raw values.",
  "rationale": "This prevents the agent from outputting non-JSON artifacts like unquoted '1 + 2', which JSONDecodeError flagged at the missing delimiter, by forcing such content into a properly quoted, escaped string.",
  "confidence": "high"
}

{
  "update_text": "If raw bytes (e.g., \\x15, 0x15) appear as literal escape sequences in input, decode the surrounding bytes first to isolate and drop them, then re-parse only the remaining valid JSON fragment instead of treating the embedded control-character escape as a valid escape.",
  "rationale": "This prevents JSONDecodeError by proactively stripping invalid byte escapes before attempting to parse, rather than failing during validation.",
  "confidence": "medium"
}

{
  "update_text": "Before parsing any input, check for octal-style backslash sequences (e.g., \\017) or other invalid escape sequences and sanitize or reject them as malformed before attempting to parse, so no garbage error is emitted from an invalid escape.",
  "rationale": "This directly addresses the 'Invalid \\escape' JSONDecodeError by pre-validating and cleaning octal/invalid backslash sequences before parsing.",
  "confidence": "medium"
}

{
  "update_text": "When input contains stray characters or fragments after the first token (e.g., a bare word like 'Bad' mixed with 'truth'), reparse only the substring up to the error position and, if no valid JSON object/array begins at the first character, respond with a sanitized fallback object rather than attempting to interpret partial tokens as values.",
  "rationale": "The error indicates the parser started reading at a non-JSON character; explicitly guiding the agent to treat any input that does not begin with a valid JSON value as malformed prevents it from echoing such fragments.",
  "confidence": "medium"
}

{
  "update_text": "When echo pitfalls cause the model to output prose or stray tab/space characters between tokens (e.g. '\\t\\tab\\tcharacter\\tabin\\tabstring\\t'), feed the entire raw output back through a strict JSON decoder before using it—on any parse failure, sanitize by stripping every \\tab, \\n, \\r, \\f, and other raw control character and trimming whitespace, then retry parsing once before falling back to a sanitized fallback object.",
  "rationale": "The error stems from the model emitting raw control characters (tabs) as literal prose instead of valid JSON, so explicitly re-parsing and scrubbing control characters will prevent feeding malformed output back into the pipeline.",
  "confidence": "medium"
}

{
  "update_text": "Never emit unescaped control characters in string values: replace line breaks, tabs, and other control characters with their proper JSON escape sequences (e.g., \\n for newlines, \\t for tabs) to avoid JSONDecodeError with 'Invalid \\escape'.",
  "rationale": "The model output a literal newline inside a string, producing an invalid backslash-escape that the JSON parser rejected; forcing explicit escaping of control characters prevents this parser error.",
  "confidence": "high"
}

{
  "update_text": "When numeric input contains an erroneous exponent-like '+-1' appended to digits (e.g., '[0e+-1]'), never transform or guess a valid JSON number from it—output the sanitized fallback object unchanged without attempting arithmetic or decoding.",
  "rationale": "The malformed value '0e+-1' is not parseable and signals the agent tried to fabricate a number rather than reject unsafe synthesis, so barring synthetic fixes prevents this decode error.",
  "confidence": "medium"
}

{
  "update_text": "When input is a sprite-style two-token string like 'XML' or 'Binary' (e.g., 'XML ', 'Binary'), never send it as unquoted raw text—always wrap it in the system's configured JSON key so it serializes as \"XML\" (valid short string) and can be read cleanly; never include fragment keys or metadata labels.",
  "rationale": "The two succeeded renders confirm the parser expects '\"XML \"\"Binary\"\"XML \"\"Binary\"\"\" as the first line of output, i.e. two JSON strings delimited together; failing to emit them as a proper quoted/list token causes the 'Property name' error.",
  "confidence": "medium"
}

{
  "update_text": "When parsing input, assume top-level keys may arrive as unquoted identifiers (e.g., {unquoted_key: ...}); pre-normalize raw input by wrapping bare IDENT-like tokens in double quotes before JSON parsing and resolve any ambiguity between a quoted string and an object by trying a quoted guess first.",
  "rationale": "The error shows the parser treated '{unquoted_key: \"keys must be quoted\"}' as malformed because top-level key names were not enclosed in double quotes.",
  "confidence": "medium"
}

{
  "update_text": "When the submitted model output itself contains injection or pollution artifacts such as user-style quotes, stray commas, or trailing text (e.g., a doubled or standalone/comma artifact), strip the entire model output down to its final JSON-producing string and re-parse that trimmed string before processing, then respond with the sanitized fallback object if parsing still fails.",
  "rationale": "The model emitted a comma that became a standalone artifact on its own line; by trimming and parsing only the model's final JSON-producing string, the stray comma is discarded and the parse proceeds cleanly.",
  "confidence": "high"
}

{
  "update_text": "When user input is a raw JSON syntax artifact such as a doubled/duplicated separator (e.g., '[,]' or 'true,,') rather than complete well-formed JSON, recognize it as malformed and respond with the sanitized fallback object instead of echoing the fragment back.",
  "rationale": "The agent echoed a partial JSON artifact back instead of treating it as invalid input, so explicitly instructing it to classify such doubled-separator fragments as malformed and respond with the fallback prevents this.",
  "confidence": "high"
}

{
  "update_text": "Never emit a trailing comma before a closing brace or bracket (e.g., write {\"a\": true} not {\"a\": true,}); validate that each JSON document parses cleanly before returning it, and if it does not, respond with the sanitized fallback object.",
  "rationale": "The error is caused by a trailing comma after the last property, which is invalid JSON; explicitly forbidding trailing commas (and confirming validity before use) prevents this class of failure.",
  "confidence": "high"
}

{
  "update_text": "When parsing a JSON object, if a value is intended to be a number but is written with a leading zero (e.g., 013) making it invalid JSON, treat the entire input as malformed and respond with the sanitized fallback object rather than attempting to preserve the leading zero.",
  "rationale": "This targets the root cause: the agent tried to keep an invalid leading-zero number; instead it should recognize leading-zero numerals as malformed JSON and return the fallback instead of throwing JSONDecodeError.",
  "confidence": "high"
}

{
  "update_text": "When reconstructing user-supplied string values (e.g., 'tab\\tcharacter\\t\\tin\\tstring'), always emit each control character using its correct JSON escape sequence when re-serializing, so a literal tab (U+0009) becomes \\\\t and a literal newline becomes \\\\n, never raw control characters",
  "rationale": "The error stems from re-serializing the user's value while keeping raw tab/newline bytes instead of converting them to \\t/\\n escapes, producing invalid JSON; an explicit re-escaping rule stops this.",
  "confidence": "high"
}

{
  "update_text": "Always pre-validate all incoming content as strict JSON: strip leading/trailing whitespace and reject any input containing raw control characters (e.g., literal newlines, tabs, or unescaped carriage returns), then only attempt to parse the cleaned, properly escaped version.",
  "rationale": "This error was caused by a literal newline in the input; sanitizing by trimming whitespace and rejecting (rather than silently parsing) raw control characters prevents malformed multi-line input from reaching the JSON parser.",
  "confidence": "high"
}

{
  "update_text": "If the model emits a value as a literal sequence with an unescaped backslash—e.g. \"line\\\"break\" or \"line  break\" rendered as an unescaped \\n—re-encode it with json.dumps() before returning so all backslashes and control characters are properly escaped.",
  "rationale": "The error stems from a raw line break being emitted between tokens, which introduces an invalid escape sequence; dictating final serialization via json.dumps prevents such leaks.",
  "confidence": "medium"
}
